import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const prisonPhysicalScenarios=['prison-ordinary','prison-dedicated'] as const;
export type PrisonPhysicalScenario=typeof prisonPhysicalScenarios[number];
export function isPrisonPhysicalScenario(name:string):name is PrisonPhysicalScenario{return (prisonPhysicalScenarios as readonly string[]).includes(name);}
export function makePrisonPhysicalScenario(name:PrisonPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none'|'metal'|'guardian';sourceGood?:boolean;blessing?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'邪祭ウーノス');assignCharacter(s,b,'侍大将のシン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level=20+(options.level??8)-gameStats(s,a).magic_level;s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;
 const card=takeCard(s,a,'a2-p13-r3c3'),maai=takeCard(s,b,'a2-p07-r1c1'),evade=takeCard(s,b,'a2-p05-r3c1'),teleport=takeCard(s,b,'a2-p06-r1c1'),fate=takeCard(s,c,'命運凶変'),guard=options.follower==='none'?null:takeCard(s,b,options.follower==='guardian'?'守護者':'メタルゴーレム'),other=options.follower==='none'?null:takeCard(s,c,'兵士'),prayer=options.follower==='guardian'?takeCard(s,a,'必勝の祈り'):null,conversion=options.sourceGood?takeCard(s,d,'a2-p04-r1c1'):null;for(const id of [a,b,c,d])trimHand(s,id,card,maai,evade,teleport,fate,...(guard?[guard]:[]),...(other?[other]:[]),...(prayer?[prayer]:[]),...(conversion?[conversion]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 if(options.blessing){const blessing=takeCard(s,b,'a2-p01-r2c1');s.players[b]!.hand.splice(s.players[b]!.hand.indexOf(blessing),1);s.deck.unshift(blessing);}
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`PRISON_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('PRISON_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('PRISON_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(other&&id===c)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:other});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(conversion){function next(target:string){for(let n=0;n<150;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>![card,conversion].includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('PRISON_PREP_TURN');}throw Error('PRISON_PREP_LIMIT');}act(a,{type:'CHANT',cardInstanceId:card});act(a,{type:'REVEAL_CHARACTER'});next(d);act(d,{type:'PLAY_TURN_CARD',cardInstanceId:'a2-p04-r1c1',targetId:a});while(s.windows?.length){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'},Array(100).fill(6));}if(s.players[a]!.faction!=='GOOD')throw Error('PRISON_CONVERSION');next(a);}return s;
}
